import {renderTokenUsage} from './token-usage-view.js';
import {dateKey,publicationDay,inDateWindow,sortMaterials,dayLabel} from './material-dates.js';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const headings=['选好方向，让故事发生','先把故事，写成你想要的样子','你定方向，Agent 完成制作','作品与过程，都在这里'];
const subtitles=['选择本次风格，找到真实内容，采集你想用的画面。','审阅整段文案和逐镜方案，确认后再进入正式制片。','按照你确认的方案，调用插件导入、剪辑、配音与导出。','预览真实成片，查看文件清单，回到可编辑的 ChatCut 工程。'];
const labels=['风格与素材','文案审阅','完整视频制作','成片与交付'];
const statuses={running:'执行中',completed:'已完成',blocked:'需处理',failed:'执行失败',cancelled:'已停止',interrupted:'已中断',needs_input:'等待补充',cancelling:'正在停止'};
const sourceTypes={x_repository:'每日 X 素材仓库',official:'官方来源',research:'研究项目 / 论文',youtube:'YouTube',other:'其他来源'};
const kindLabels={video:'视频',image:'图片',audio:'音频',article:'内容',paper:'研究资料'};
let cacheQuery='',cacheFilter='all',cacheWindow='all',cacheLimit=24,librarySyncing=false;
let state,step=0,selected=new Set(),activeId=null,pollTimer,saveTimer,toastTimer,settingsDirty=false,settingsEpoch=0,planDirty=false,saving=Promise.resolve(),busy=false;
if(!Number.isInteger(step)||step<0||step>3)step=0;
async function api(url,data){const response=await fetch(url,data===undefined?{cache:'no-store'}:{method:'POST',headers:{'Content-Type':'application/json','X-Video-Demo':'1',...(state?.project?.id?{'X-Video-Project':state.project.id}:{})},body:JSON.stringify(data)});const value=await response.json();if(!response.ok)throw new Error(value.error||'请求失败。');return value;}
function toast(message){$('#toast').textContent=message;$('#toast').classList.remove('hidden');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.add('hidden'),3500);}
function error(message){$('#error-banner').textContent=message;$('#error-banner').classList.remove('hidden');}
function clearError(){$('#error-banner').classList.add('hidden');}
function currentSettings(){const p=state.project;return {topic:p.topic,purpose:p.purpose,duration:Number($('#duration').value),ratio:$('#ratio').value,fps:p.fps,language:p.language,narration:p.narration,captions:p.captions,music:p.music,voiceDirection:p.voiceDirection,styleSelector:p.styleSelector,styleDescription:p.styleDescription,outputRoot:$('#output-root').value,selected:[...selected]};}
function markSettings(){settingsDirty=true;settingsEpoch++;$('#save-status').textContent='有待保存的修改';clearTimeout(saveTimer);saveTimer=setTimeout(()=>saveSettings().catch(e=>error(e.message)),650);}
async function saveSettings(){clearTimeout(saveTimer);if(!settingsDirty)return;const snapshot=currentSettings(),epoch=settingsEpoch;saving=saving.catch(()=>{}).then(async()=>{const response=await api('/api/project',snapshot);state.project=response.project;settingsDirty=settingsEpoch!==epoch;$('#save-status').textContent=settingsDirty?'有待保存的修改':'已保存到本机';renderNav();});await saving;}
function fillSettings(){const p=state.project;$('#duration').value=p.duration;$('#ratio').value=p.ratio;$('#output-root').value=p.outputRoot;$('#spec-summary').textContent=`${p.duration} 秒 · ${p.ratio}`;$('#project-name').textContent=p.title;$('#breadcrumb-title').textContent=p.title;$('#project-count').textContent=state.projects?.length||1;}
function renderNav(){const p=state.project;const done=[p.selected.length>0,!!p.approval,!!p.deliveries.length,!!p.deliveries.length];document.querySelectorAll('[data-step]').forEach(b=>{const n=Number(b.dataset.step);b.classList.toggle('active',n===step);b.querySelector('.step-check').textContent=done[n]?'✓':'';b.setAttribute('aria-current',n===step?'step':'false');});document.querySelectorAll('[data-flow]').forEach(el=>{const n=Number(el.dataset.flow);el.classList.toggle('current',n===step);el.classList.toggle('done',done[n]&&n!==step);});}
function smallAction(action,title){return `<button class="button secondary small-button" data-action="${action}" ${busy?'disabled':''}>✳ ${title}</button>`;}
function empty(icon,title,message){return `<div class="editor-placeholder"><span class="empty-art">${icon}</span><strong>${title}</strong><p>${message}</p></div>`;}
function matchingCache(source){return cachedEntries().find(c=>c.availability==='available'&&source.url&&source.url===c.url&&(!source.expectedSha256||source.expectedSha256===c.sha256)&&(!source.repositoryCommit||!c.repositoryCommit||source.repositoryCommit===c.repositoryCommit));}
function sourceThumbnail(source){const known=(state.library?.candidates||[]).find(c=>c.url===source.url&&(!source.repositoryCommit||c.repositoryCommit===source.repositoryCommit||source.expectedSha256&&c.expectedSha256===source.expectedSha256));return source.thumbnailUrl||known?.thumbnailUrl||'';}
function sourceTaskStatus(){const job=state.project.jobs.find(j=>j.id===activeId&&['discover','collect','plan'].includes(j.action));if(!job||!['running','cancelling'].includes(job.status))return '';return `<div class="source-task-summary"><span class="source-task-spinner" aria-hidden="true"></span><div><strong>${job.action==='discover'?'正在检索和核实素材':job.action==='plan'?'正在分析画面并生成文案与分镜':'正在采集并校验文件'}</strong><p>${esc(job.events.at(-1)?.message||'独立任务已提交')}</p><small>${job.action==='plan'?'会复用已有画面分析，生成后可在这里审阅和修改。':'可以继续浏览缓存；完成后会显示本轮结果。'}</small></div></div>`;}
function sourceCard(s){
  const ready=s.status==='ready',cached=ready?null:matchingCache(s),local=cached||s,thumbnailUrl=sourceThumbnail(s);
  const mediaBase=(cached?'/api/library/media/':'/api/media/')+local.id;
  const previewTarget=cached?`data-cache-preview="${cached.id}"`:`data-preview="${s.id}"`;
  const preview=ready||cached?(local.kind==='image'?`<img src="${mediaBase}" alt="${esc(s.title)}" loading="lazy">`:local.thumbnailPath?`<img src="${mediaBase}?thumbnail=1" alt="${esc(s.title)}" loading="lazy">`:`<span>${local.kind==='audio'?'♫':'▷'}</span>`):thumbnailUrl?`<img src="${esc(thumbnailUrl)}" alt="" loading="lazy" referrerpolicy="no-referrer">`:'<span class="preview-unavailable">暂无真实预览</span>';
  return `<article class="source-card ${selected.has(s.id)?'selected':''}"><button class="source-preview" ${previewTarget} aria-label="预览 ${esc(s.title)}">${preview}<span class="source-badge">${kindLabels[s.kind]} · ${ready?'已保存本地':cached?'缓存可用':'仅链接'}</span></button><div class="source-body"><div class="source-title"><button ${previewTarget}>${esc(s.title)}</button>${ready?`<input type="checkbox" data-select="${s.id}" aria-label="选择 ${esc(s.title)}" ${selected.has(s.id)?'checked':''} ${busy?'disabled':''}>`:''}</div><p>${esc(s.description||s.author||'等待检查内容')}</p><div class="source-origin">${esc(sourceTypes[s.sourceType]||sourceTypes.other)}</div><div class="source-meta"><span>${ready||cached?(local.duration?Number(local.duration).toFixed(1)+' 秒':local.width+' × '+local.height):(s.publishedAt||'日期未知')}</span><span>${s.author?esc(s.author):ready||cached?'本地文件可用':'待采集媒体'}</span></div><div class="source-bottom">${s.url?`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">原始来源 ↗</a>`:'<span>本地文件</span>'}${ready?`<button class="text-button" data-preview="${s.id}">查看预览</button>`:cached?`<button class="button secondary small-button" data-cache-use="${cached.id}" ${busy?'disabled':''}>选用已有缓存</button>`:`<button class="button secondary small-button" data-collect="${s.id}" ${busy?'disabled':''}>采集素材 ↓</button>`}</div></div></article>`;
}

const dimensionLabels={narrative:'叙事结构',language:'语言表达',shots:'镜头组织',pacing:'节奏',graphics:'画面图形',captions:'字幕',audio:'声音',transitions:'转场'};
const basisLabels={observed:'来自观察记录',inferred:'分析推断',user_direction:'用户明确要求'};
const referenceKinds={video:'视频参考',script:'脚本 / 分析记录',user_direction:'用户要求'};
function styleEntries(){return state.catalog.styleBrowser?.entries||[];}
function styleCard(s){const chosen=state.project.styleSelector===s.selector&&s.origin==='library';return `<article class="real-style-card ${chosen?'selected':''}"><div class="real-style-top"><span class="style-version">v${s.version} · ${s.origin==='library'?'已导入':'仓库风格包'}</span><span class="style-validation">${s.validation_status==='unverified'?'复现未验证':esc(s.validation_status)}</span></div><h3>${esc(s.name)}</h3><p>${esc(s.description)}</p><div class="style-counts">${s.ruleCount} 条规则 · ${s.referenceCount} 项参考</div><div class="real-style-actions"><button class="text-button" data-style-detail="${esc(s.key)}">规则与案例 ↗</button><button class="button secondary small-button" data-style-use="${esc(s.key)}" ${busy||chosen?'disabled':''}>${chosen?'✓ 已选择':'选择此风格'}</button></div></article>`;}
function renderRealStyles(){const entries=styleEntries(),current=entries.filter(s=>!s.historical),old=entries.filter(s=>s.historical);return `${current.length?`<div class="real-style-grid">${current.map(styleCard).join('')}</div>`:'<p class="helper-text">尚未发现真实风格。可导入自己的风格包；这里不会补充示例风格。</p>'}${old.length?`<details class="style-history"><summary>历史版本 · ${old.length} 项</summary><div class="real-style-grid">${old.map(styleCard).join('')}</div></details>`:''}${(state.catalog.styleBrowser?.errors||[]).length?`<details class="style-errors"><summary>有 ${state.catalog.styleBrowser.errors.length} 项风格未通过读取校验</summary>${state.catalog.styleBrowser.errors.map(e=>`<p>${esc(e.selector||e.name)}：${esc(e.error)}</p>`).join('')}</details>`:''}`;}
async function useStyle(key){if(busy)return;clearError();await saveSettings();const next=await api('/api/styles/select',{key});state=next;selected=new Set(state.project.selected);render();toast('已选择本次风格。');if($('#style-dialog').open)await showStyle(next.selection.key);}
async function showStyle(key){const detail=await api('/api/styles/detail?key='+encodeURIComponent(key));const refs=detail.references;const chosen=state.project.styleSelector===detail.selector&&detail.origin==='library';
  const referenceCard=r=>{const analysis=r.analysis;return `<article class="style-reference" id="style-ref-${esc(r.id)}"><span class="style-version">${referenceKinds[r.kind]||esc(r.kind)} · ${esc(r.id)}</span><h4>${esc(r.title||r.file_name||r.id)}</h4>${r.analyzed_ranges?.length?`<p>分析范围：${esc(r.analyzed_ranges.join('；'))}</p>`:''}${analysis?`<p>${esc(analysis.source_summary||'')}</p><dl class="case-analysis">${[['speaking','讲述方式'],['description','结构'],['concept','推进与节奏'],['camera','镜头观察'],['transfer','可迁移方法'],['avoid','使用边界']].filter(([k])=>analysis[k]).map(([k,label])=>`<dt>${label}</dt><dd>${esc(analysis[k])}</dd>`).join('')}</dl>${analysis.shots?.length?`<details><summary>查看已记录的镜头分析</summary><ul>${analysis.shots.map(s=>`<li>${esc(s)}</li>`).join('')}</ul></details>`:''}`:''}${r.limitations?`<p class="evidence-limitation">分析边界：${esc(r.limitations)}</p>`:''}<div class="reference-actions">${r.url?`<a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">打开参考来源 ↗</a>`:''}${r.readable?`<button class="text-button" data-style-evidence="${esc(r.id)}" data-style-key="${esc(key)}">查看原始证据文本</button>`:!r.url?`<span class="helper-text">原文件未包含在当前风格证据中</span>`:''}</div></article>`;};
  $('#style-detail').innerHTML=`<span class="eyebrow">VIDEO STUDIO · REAL STYLE</span><h2 id="style-detail-title">${esc(detail.name)} <small>v${detail.version}</small></h2><p>${esc(detail.description)}</p><div class="style-detail-status">${detail.origin==='library'?'来源：已导入的个人风格库':'来源：仓库中的可选风格包 '+esc(detail.pack)} · ${detail.validation_status==='unverified'?'尚未完成成片复现验证':esc(detail.validation_status)}</div><button class="button primary" data-style-use="${esc(key)}" ${busy||chosen?'disabled':''}>${chosen?'✓ 已选择':'选择此风格'}</button><p class="helper-text">查看规则和案例不会开始制作。选用风格只作用于本期，规格和声音以本次设置为准。</p><section class="style-detail-section"><h3>跨题材适配</h3><p>${esc(detail.adaptation)}</p></section><section class="style-detail-section"><h3>制作规则与检查方法</h3>${detail.rules.map(r=>`<article class="workbench-style-rule"><div><strong>${dimensionLabels[r.dimension]||esc(r.dimension)}</strong><span>${basisLabels[r.basis]||esc(r.basis)}</span></div><p>${esc(r.instruction)}</p><p class="rule-check">检查：${esc(r.check)}</p><div class="rule-evidence">依据：${r.evidence.map(e=>`<a href="#style-ref-${esc(e.reference_id)}">${esc(e.reference_id)} · ${esc(e.location)}</a>`).join(' / ')}</div></article>`).join('')}</section>${detail.material_requirements.length?`<section class="style-detail-section"><h3>对应素材要求</h3>${detail.material_requirements.map(m=>`<article class="material-rule"><strong>${esc(m.role)}</strong><p>寻找：${esc(m.search_hint)}</p><p>采用标准：${esc(m.acceptance)}</p><small>关联规则 ${esc(m.rule_id)}</small></article>`).join('')}</section>`:''}<section class="style-detail-section"><h3>参考案例与证据</h3><p class="helper-text">以下内容来自风格文件和附带分析记录。参考案例用于理解表达方式，不会自动变成新视频素材。</p>${refs.filter(r=>r.kind==='video').map(referenceCard).join('')}<details class="supporting-evidence"><summary>脚本、用户要求与分析原文 · ${refs.filter(r=>r.kind!=='video').length} 项</summary>${refs.filter(r=>r.kind!=='video').map(referenceCard).join('')}</details></section>${detail.unknown_dimensions.length?`<p class="evidence-limitation">未观察维度：${detail.unknown_dimensions.map(d=>dimensionLabels[d]||esc(d)).join('、')}</p>`:'<p class="helper-text">风格文件覆盖了全部维度；覆盖不代表已通过完整声画复现验收。</p>'}<details class="style-skill-source"><summary>查看对应风格技能原文</summary><pre>${esc(detail.skill)}</pre></details><section id="style-evidence-output" class="hidden" aria-live="polite"></section>`;
  if(!$('#style-dialog').open)$('#style-dialog').showModal();
}
async function showEvidence(key,id){const ref=await api('/api/styles/reference?key='+encodeURIComponent(key)+'&id='+encodeURIComponent(id));const target=$('#style-evidence-output');target.classList.remove('hidden');target.innerHTML=`<h3>${esc(ref.name)}</h3><p class="media-hash">SHA-256 ${esc(ref.sha256)}</p><pre>${esc(ref.text)}</pre>`;target.scrollIntoView({behavior:'smooth',block:'start'});}

function cachedEntries(){return state.library?.entries||[];}
function cachedCandidates(){return (state.library?.candidates||[]).filter(c=>!c.localCacheIds?.length);}
function allCachedContent(){return [...cachedEntries().map(s=>{const c=(state.library?.candidates||[]).find(c=>c.localCacheIds?.includes(s.id));return {...s,publishedAt:c?.publishedAt||s.publishedAt,batchDate:c?.batchDate||s.batchDate,collectedAt:c?.collectedAt||s.collectedAt,cacheType:'media'};}),...cachedCandidates().map(s=>({...s,cacheType:'candidate'}))];}
function filteredCache(){const query=cacheQuery.trim().toLowerCase();return sortMaterials(allCachedContent().filter(s=>(cacheFilter==='all'||s.cacheType===cacheFilter)&&inDateWindow(s,cacheWindow)&&(!query||[s.title,s.description,s.author,s.publishedAt,s.eventDate,s.batchDate,...(s.origins||[]).flatMap(o=>[o.topic,o.query])].join(' ').toLowerCase().includes(query))));}
function materialDates(s){return `<div class="material-date"><strong>${publicationDay(s)?'发布 ':''}${esc(dayLabel(s.publishedAt))}</strong>${s.batchDate?`<span>收集批次 ${esc(s.batchDate)}</span>`:''}</div>`;}

function cachedCard(s){const available=s.availability==='available';const inUse=state.project.sources.some(p=>p.sha256===s.sha256&&selected.has(p.id));const base='/api/library/media/'+s.id;const preview=available?(s.kind==='image'?`<img src="${base}" alt="${esc(s.title)}" loading="lazy">`:s.thumbnailPath?`<img src="${base}?thumbnail=1" alt="${esc(s.title)}" loading="lazy">`:`<span>${s.kind==='audio'?'♫':'▷'}</span>`):'<span class="preview-unavailable">文件需重新采集</span>';
  return `<article class="source-card cached-card ${inUse?'selected':''}"><button class="source-preview" data-cache-preview="${s.id}" aria-label="预览缓存 ${esc(s.title)}" ${!available?'disabled':''}>${preview}<span class="source-badge">${esc(kindLabels[s.kind])} · ${available?'本地缓存':s.availability==='missing'?'文件已移走':'文件已变化'}</span></button><div class="source-body"><div class="source-title"><button data-cache-preview="${s.id}" ${!available?'disabled':''}>${esc(s.title)}</button></div><p>${esc(s.description||s.author||'已保存的真实素材')}</p>${materialDates(s)}<div class="source-origin">${esc(sourceTypes[s.sourceType]||sourceTypes.other)} · 已下载</div><div class="source-meta"><span>${s.duration?Number(s.duration).toFixed(1)+' 秒':s.width+' × '+s.height}</span><span>${(s.bytes/1024/1024).toFixed(2)} MB</span></div><div class="source-bottom"><button class="text-button" data-cache-preview="${s.id}" ${!available?'disabled':''}>预览</button><button class="button secondary small-button" data-cache-use="${s.id}" ${busy||!available||inUse?'disabled':''}>${inUse?'✓ 本期已选用':'选用到本期'}</button></div></div></article>`;
}
function candidateCard(s){const collecting=s.acquisition?.status==='running'||s.acquisition?.status==='cancelling';const failed=['failed','blocked','interrupted','cancelled'].includes(s.acquisition?.status);const origin=(s.origins||[]).find(o=>o.reason)||s.origins?.[0];const preview=s.thumbnailUrl?`<img src="${esc(s.thumbnailUrl)}" alt="原来源缩略图" loading="lazy" referrerpolicy="no-referrer">`:'<span class="candidate-preview-label">↗<small>来源记录 · 媒体未采集</small></span>';
  return `<article class="source-card candidate-cache-card"><button class="source-preview" data-candidate-preview="${s.id}" aria-label="查看缓存候选 ${esc(s.title)}">${preview}<span class="source-badge candidate-badge">${esc(kindLabels[s.kind])} · ${collecting?'采集中':'未采集'}</span></button><div class="source-body"><div class="source-title"><button data-candidate-preview="${s.id}">${esc(s.title)}</button></div><p>${esc(s.description||origin?.reason||'已缓存来源记录，尚未下载媒体。')}</p>${materialDates(s)}<div class="source-origin">${esc(sourceTypes[s.sourceType]||sourceTypes.other)}${s.repositoryMedia?.length?' · '+s.repositoryMedia.filter(m=>m.type==='video').length+' 段视频 / '+s.repositoryMedia.filter(m=>m.type==='image').length+' 张图片':''}</div><div class="source-meta"><span>${s.sourceType==='x_repository'?'原帖内容待复核':'已保存检索记录'}</span><span>${esc(s.author||'作者待核实')}</span></div>${failed?`<p class="candidate-attempt">上次未完成：${esc(s.acquisition.error||s.acquisition.summary||'可重新尝试采集')}</p>`:''}<div class="source-bottom"><button class="text-button" data-candidate-preview="${s.id}">查看详情</button><button class="button secondary small-button" data-candidate-collect="${s.id}" ${busy||collecting?'disabled':''}>${collecting?'正在采集…':failed?'重新采集 ↓':'采集到本地 ↓'}</button></div></div></article>`;
}
function cacheResults(){const entries=filteredCache(),shown=entries.slice(0,cacheLimit),groups=new Map();for(const s of shown){const day=publicationDay(s)||'unknown';if(!groups.has(day))groups.set(day,[]);groups.get(day).push(s);}return entries.length?`<p class="cache-result-count">显示 ${shown.length} / ${entries.length} 条 · 按发布日期从新到旧 · UTC+8</p>${[...groups].map(([day,items])=>`<section class="material-day"><h3>${esc(day==='unknown'?'发布日期待核实':dayLabel(day))}<span>${entries.filter(s=>(publicationDay(s)||'unknown')===day).length} 条</span></h3><div class="sources-grid">${items.map(s=>s.cacheType==='candidate'?candidateCard(s):cachedCard(s)).join('')}</div></section>`).join('')}${entries.length>cacheLimit?'<button id="cache-more" class="button secondary small-button cache-more">继续查看剩余内容 ↓</button>':''}`:`<div class="cache-empty">${allCachedContent().length?'此范围内没有匹配内容，可切换日期、关键词或采集状态。':'还没有缓存。可更新每日仓库目录，或按本期题材搜索。'}</div>`;}
function repositoryCoverage(){const sync=state.library?.repositorySync;if(!sync)return '<p class="helper-text">可读取插件配置的每日 X 素材仓库，展示完整候选目录。</p>';const ready=sync.batches.filter(b=>b.status==='ready'),pending=sync.batches.filter(b=>b.status==='pending');return `<div class="repository-coverage"><strong>每日仓库 · ${ready.length} 个已就绪批次 / ${sync.sourceCount} 条内容</strong><p>收集批次：${ready.map(b=>`${esc(b.date)}（${b.imported}/${b.total}）`).join('、')||'暂无'}。${pending.length?'上传中：'+pending.map(b=>esc(b.date)).join('、')+'，暂不可采集。':''}</p><small>检查于 ${esc(new Date(sync.checkedAt).toLocaleString('zh-CN',{timeZone:'Asia/Singapore',hour12:false}))} · 批次日期与原帖发布日期分别标注 · 仅更新文字目录</small>${sync.errors.length?`<details><summary>${sync.errors.length} 项未能读取</summary>${sync.errors.map(e=>`<p>${esc(e.title)}：${esc(e.error)}</p>`).join('')}</details>`:''}</div>`;}
function renderLibrary(){const media=cachedEntries(),candidates=cachedCandidates(),total=media.length+candidates.length;return `<section id="material-library" class="material-library" aria-label="素材库"><div class="section-heading"><h2>素材库 <span class="sub-count">${total}</span></h2><div class="library-actions"><button class="text-button" id="cache-refresh">刷新本地 ↻</button><button class="button secondary small-button" id="repository-sync" ${busy||librarySyncing?'disabled':''}>${librarySyncing?'正在读取仓库…':'更新仓库候选 ↻'}</button></div></div><p class="source-skill-description">每日仓库的完整目录、历史搜索候选与本地素材。先浏览，再点击需要的内容采集到本地。</p>${repositoryCoverage()}<div class="cache-filters" aria-label="缓存内容筛选">${[['all','全部',total],['candidate','未采集',candidates.length],['media','已下载',media.length]].map(([key,label,count])=>`<button class="cache-filter ${cacheFilter===key?'active':''}" data-cache-filter="${key}" aria-pressed="${cacheFilter===key}">${label} <span>${count}</span></button>`).join('')}</div><div class="cache-date-filters" aria-label="发布日期筛选">${[['all','全部日期'],['3','近 3 天'],['7','近 7 天'],['30','近 30 天'],['unknown','日期待核实']].map(([key,label])=>`<button class="cache-filter ${cacheWindow===key?'active':''}" data-cache-window="${key}" aria-pressed="${cacheWindow===key}">${label} <span>${allCachedContent().filter(s=>inDateWindow(s,key)).length}</span></button>`).join('')}</div><input id="cache-query" class="cache-query" value="${esc(cacheQuery)}" placeholder="搜索标题、作者、日期或素材需求" aria-label="搜索素材缓存"><div id="cache-results">${cacheResults()}</div>${state.library?.errors?.length?`<details class="cache-errors"><summary>有 ${state.library.errors.length} 项缓存未完成，查看原因</summary>${state.library.errors.map(e=>`<p>${esc(e.title)}：${esc(e.error)}</p>`).join('')}</details>`:''}</section>`;}
async function syncRepository(){if(busy||librarySyncing)return;librarySyncing=true;$('#material-library').outerHTML=renderLibrary();try{state.library=await api('/api/library/sync-repository',{});toast('仓库候选已更新，点击需要的内容后再下载。');}catch(e){error(e.message);toast(e.message);}finally{librarySyncing=false;$('#material-library').outerHTML=renderLibrary();}}
async function previewCandidate(id){const s=(state.library?.candidates||[]).find(c=>c.id===id);if(!s)return;const origin=(s.origins||[]).find(o=>o.reason)||s.origins?.[0];$('#media-detail').innerHTML=`<span class="eyebrow">缓存候选 · 未采集</span><h2>${esc(s.title)}</h2>${s.thumbnailUrl?`<div class="media-player"><img src="${esc(s.thumbnailUrl)}" alt="来源缩略图" referrerpolicy="no-referrer"></div>`:''}<p>${esc(s.description)}</p><p class="helper-text">这里保存了链接和检索记录，媒体尚未下载。</p><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">打开原始来源 ↗</a><p class="helper-text">${esc(sourceTypes[s.sourceType]||sourceTypes.other)} · ${esc(s.author||'作者待核实')} · 权利状态：${esc(s.rights)}</p>${materialDates(s)}<p class="helper-text">原帖时间：${esc(s.publishedAt||'未知')}<br>仓库收集时间：${esc(s.collectedAt||'未记录')}<br>本机目录更新：${esc(s.lastSeenAt)}</p>${s.repositoryMedia?.length?`<div class="repository-media-list"><strong>此条目包含的媒体</strong>${s.repositoryMedia.map(m=>`<p>${m.type==='video'?'视频':'图片'} · ${m.width} × ${m.height}${m.duration?' · '+Number(m.duration).toFixed(1)+' 秒':''} · ${(m.bytes/1024/1024).toFixed(2)} MB</p>`).join('')}</div>`:''}${s.postText?`<details><summary>仓库原始内容记录</summary><pre class="candidate-post">${esc(s.postText)}</pre></details>`:''}${s.dateEvidence||origin?.dateEvidence?`<p class="helper-text">日期依据：${esc(s.dateEvidence||origin.dateEvidence)}</p>`:''}${origin?.topic?`<p class="helper-text">原搜索主题：${esc(origin.topic)}</p>`:''}${origin?.reason?`<p class="candidate-history-reason">当时的筛选理由：${esc(origin.reason)}</p>`:''}${s.topicFit||s.styleFit?`<dl class="source-fit"><dt>原题材适配</dt><dd>${esc(s.topicFit||'未记录')}</dd><dt>原风格适配</dt><dd>${esc(s.styleFit||'未记录')}</dd></dl>`:''}${s.verification?`<p class="helper-text">历史核实记录：${esc(s.verification)}</p>`:''}${s.caveats?.length||origin?.caveats?.length?`<p class="source-caveats">待核实：${[...(s.caveats||[]),...(origin?.caveats||[])].map(esc).join('；')}</p>`:''}${s.kind==='video'?`<div class="collect-range"><label>截取起点（秒）<input id="collect-start" type="number" min="0" value="${s.start||0}"></label><label>截取终点（秒，0 表示由 Agent 选取）<input id="collect-end" type="number" min="0" value="${s.end||0}"></label></div>`:''}<button class="button primary" data-candidate-collect="${id}" ${busy?'disabled':''}>调用素材采集，下载到本地 ↓</button>`;$('#media-dialog').dataset.candidateId=id;$('#media-dialog').showModal();}
async function collectCandidate(id){if(busy)return;clearError();try{await saveSettings();const inPreview=$('#media-dialog').open&&$('#media-dialog').dataset.candidateId===id;const range=inPreview?{start:Number($('#collect-start')?.value)||0,end:Number($('#collect-end')?.value)||0}:{};$('#media-dialog').close();const result=await api('/api/library/collect',{candidateId:id,...range});if(result.job)activeId=result.job.id;await refresh();if(result.job)schedulePoll();else toast('已有本地缓存，可直接预览或选用。');}catch(e){error(e.message);toast(e.message);}}

async function useCached(id){if(busy)return;clearError();try{await saveSettings();const next=await api('/api/library/use',{id});state=next;selected=new Set(state.project.selected);if($('#media-dialog').open)$('#media-dialog').close();render();toast('已从本地缓存选用，无需重新下载。');}catch(e){error(e.message);toast(e.message);}}
function sourceEventCard(event){
  const sources=event.source_ids.map(id=>state.project.sources.find(s=>s.id===id)).filter(Boolean);
  if(!sources.length)return '';
  const primary=sources.find(s=>s.status!=='ready')||sources[0];
  return `<article class="source-event"><div class="source-event-heading"><span class="recommendation-rank">${event.decision==='top5'?'推荐 '+event.rank:event.decision==='hold'?'待核实':'备选'}</span><h3>${esc(event.title)}</h3></div><p class="recommendation-reason">${esc(event.reason)}</p>${event.date_evidence?`<p class="source-date-evidence">日期依据：${esc(event.date_evidence)}</p>`:''}${sourceCard(primary)}${sources.length>1?`<details class="related-sources"><summary>同一内容的其他来源 · ${sources.length-1}</summary>${sources.filter(s=>s.id!==primary.id).map(s=>`<div><button class="text-button" data-preview="${s.id}">${esc(s.title)}</button><span>${esc(sourceTypes[s.sourceType]||sourceTypes.other)} · ${s.status==='ready'?'已保存本地':'仅链接'}</span>${s.status!=='ready'?`<button class="text-button" data-collect="${s.id}" ${busy?'disabled':''}>采集 ↓</button>`:''}</div>`).join('')}</details>`:''}${event.caveats?.length?`<p class="source-caveats">待核实：${event.caveats.map(esc).join('；')}</p>`:''}</article>`;
}
function renderSources(){const p=state.project;const ready=p.sources.filter(s=>s.status==='ready');const review=p.sourceReview;const current=review&&review.topic===p.topic&&review.style===p.styleSelector?review:null;const grouped=new Set((current?.events||[]).flatMap(e=>e.source_ids));const candidates=p.sources.filter(s=>s.status!=='ready'&&!grouped.has(s.id));const top=(current?.events||[]).filter(e=>e.decision==='top5').sort((a,b)=>a.rank-b.rank);const other=(current?.events||[]).filter(e=>e.decision!=='top5');return `
<section class="style-setup"><div class="section-heading"><h2>选择插件中的真实风格</h2></div>${renderRealStyles()}</section>
<section class="source-search"><div class="section-heading"><h2>用插件搜索素材</h2><button class="text-button" id="source-skill-rules">查看采集规则 ↗</button></div><p class="source-skill-description">素材采集工具 · 按本期题材和所选风格查找来源、核实并推荐，点击采集后保存到本机。</p><div class="search-row"><input id="search-query" placeholder="输入素材关键词，例如：机器人走进工厂"><button class="button primary" data-action="discover" ${busy?'disabled':''}>✳ 按插件搜索素材</button></div><div class="source-import-tabs"><button class="text-button" id="add-url-toggle">＋ 添加内容链接</button><label class="upload-label">↑ 上传本地素材<input type="file" id="upload-files" accept="video/*,image/png,image/jpeg,image/webp,image/gif,audio/*" multiple ${busy?'disabled':''}></label><button class="text-button" id="local-path-toggle">从本机路径导入</button></div><div id="url-box" class="hidden inline-field"><input id="source-url" placeholder="公开网页、视频或图片链接"><button class="button secondary small-button" id="add-url">添加内容</button></div><div id="local-box" class="hidden inline-field"><input id="local-path" placeholder="本地媒体文件的完整路径"><button class="button secondary small-button" id="add-local">导入素材</button></div></section>
<div id="source-task-status" role="status" aria-live="polite">${sourceTaskStatus()}</div>
<div id="current-materials"></div>
${ready.length?`<div class="section-heading"><h2>本期素材 <span class="sub-count">${ready.length}</span></h2><span class="section-note">勾选用于本期 · 已选 ${p.selected.length} 条</span></div><div class="sources-grid">${ready.map(sourceCard).join('')}</div>`:''}
${current?`<section id="source-review" class="source-review"><div class="section-heading candidates-heading"><h2>本轮推荐 <span class="sub-count">${top.length}</span></h2><a class="text-button" href="/api/source-reports/${current.jobId}" download>完整检索与筛选记录 ↓</a></div><p class="source-review-scope">${esc(current.scope)} · ${current.events.length} 项内容 / ${grouped.size} 个来源</p><p class="helper-text">推荐由素材采集 skill 给出；采集并勾选后，才会用于本期制作。</p>${top.length?`<div class="source-event-grid">${top.map(sourceEventCard).join('')}</div>`:'<p class="helper-text">本轮没有足够证据支持推荐，具体原因见待核实项。</p>'}${other.length?`<details class="source-reserves"><summary>其他候选与待核实 · ${other.length} 项</summary><div class="source-event-grid">${other.map(sourceEventCard).join('')}</div></details>`:''}${current.gaps.length?`<div class="source-search-gaps"><strong>检索时的缺口与待核实项</strong>${current.gaps.map(g=>`<p>${esc(g)}</p>`).join('')}</div>`:''}</section>`:''}
${review&&!current?'<p class="helper-text">主题或风格已改变，可重新搜索以更新推荐；已有素材仍保留。</p>':''}
${candidates.length?`<div class="section-heading candidates-heading"><h2>其他内容 <span class="sub-count">${candidates.length}</span></h2><span class="section-note">点击内容采集对应素材</span></div><div class="sources-grid">${candidates.map(sourceCard).join('')}</div>`:''}
${renderLibrary()}
${!p.sources.length?`<p class="source-project-empty">${busy?'当前任务正在执行，完成后会在这里更新；缓存素材仍可预览。':cachedEntries().length?'本期还未选材。可以选用上方缓存，也可以继续搜索新内容。':'本期还没有素材，可先搜索内容或导入本地文件。'}</p>`:''}`;}

function planFromForm(){const current=state.project.plan;if(!current)return null;return {...current,script:$('#script-editor').value,gaps:$('#plan-gaps').value.split('\n').map(s=>s.trim()).filter(Boolean),limitations:$('#plan-limitations').value.split('\n').map(s=>s.trim()).filter(Boolean),shots:[...document.querySelectorAll('.shot-edit')].map((el,i)=>{const sourceIds=[...el.querySelector('[data-shot-field="sourceIds"]').selectedOptions].map(o=>o.value);return {...current.shots[i],from:Number(el.querySelector('[data-shot-field="from"]').value),to:Number(el.querySelector('[data-shot-field="to"]').value),sourceIds,narration:el.querySelector('[data-shot-field="narration"]').value,visual:el.querySelector('[data-shot-field="visual"]').value,screenText:el.querySelector('[data-shot-field="screenText"]').value,transition:el.querySelector('[data-shot-field="transition"]').value};})};}
async function savePlan(){if(!planDirty)return;await saveSettings();const response=await api('/api/plan',{plan:planFromForm()});state.project.plan=response.plan;state.project.approval=null;planDirty=false;$('#save-status').textContent='方案修改已保存';}
function renderReview(){const p=state.project,plan=p.plan;if(!plan)return `<div class="section-heading"><h2>生成可审阅的文案与分镜</h2>${smallAction('plan','生成文案与分镜')}</div><p class="stage-description">结合当前风格和 ${p.selected.length} 条真实素材，先给出完整方案。你确认之前，不生成配音、不创建正式剪辑。</p><div id="source-task-status" role="status" aria-live="polite">${sourceTaskStatus()}</div>${empty('Aa','先把要讲的故事说清楚。','选择素材后，点击「生成文案与分镜」。<br>生成结果会在这里开放编辑。')}`;
  const banner=plan.stale?'<div class="review-state warning">制作要求或素材已改变。请重新生成方案，或检查并保存当前修改后再确认。</div>':p.approval?`<div class="review-state confirmed">✓ 当前方案 v${plan.version} ${p.approval.authority?.kind==='delegated_review'?'已按本次委托完成审阅':p.approval.authority?.kind==='user_message'?'已按你的确认保存':'已确认'}，内容改动会使确认失效。</div>`:'<div class="review-state">请 review 文案与每个镜头，确认后进入正式制作。</div>';
  return `<div class="section-heading"><h2>${esc(plan.title)} <span class="sub-count">v${plan.version}</span></h2>${smallAction('plan','重新生成方案')}</div>${banner}${plan.gaps.length?`<div class="review-blocker" role="status"><strong>还有 ${plan.gaps.length} 项待补输入，解决后才能确认</strong><p>请检查下方「待补输入」。已在方案中避免的未核实内容，可以连同处理方式保存在「已知限制与处理」；修改后先保存。</p></div>`:''}<p class="stage-description">${esc(plan.summary)}</p><label class="editor-label" for="script-editor">完整文案 / 屏幕叙事</label><textarea id="script-editor" class="script-editor" maxlength="24000" ${busy?'disabled':''}>${esc(plan.script)}</textarea><div class="section-heading shot-heading"><h2>逐镜方案</h2><span class="section-note">以下时间为规划值，制片时按实际音频调整</span></div><div class="shot-edit-list">${plan.shots.map((s,i)=>`<article class="shot-edit"><div class="shot-edit-header"><span class="shot-number">${String(i+1).padStart(2,'0')}</span><span>预计</span><input type="number" step="0.01" data-shot-field="from" value="${s.from}" aria-label="镜头 ${i+1} 开始秒数"><span>—</span><input type="number" step="0.01" data-shot-field="to" value="${s.to}" aria-label="镜头 ${i+1} 结束秒数"><span>秒</span></div><div class="shot-edit-fields"><label>旁白<textarea data-shot-field="narration" rows="2">${esc(s.narration)}</textarea></label><label>画面与构图<textarea data-shot-field="visual" rows="2">${esc(s.visual)}</textarea></label><label>屏幕文字<textarea data-shot-field="screenText" rows="2">${esc(s.screenText)}</textarea></label><label>剪辑 / 转场<textarea data-shot-field="transition" rows="2">${esc(s.transition)}</textarea></label><label class="full-width">对应已选素材<select multiple data-shot-field="sourceIds" aria-label="镜头 ${i+1} 对应素材">${p.sources.filter(x=>p.selected.includes(x.id)).map(x=>`<option value="${x.id}" ${s.sourceIds.includes(x.id)?'selected':''}>${esc(x.title)}</option>`).join('')}</select><small>可多选；纯文字卡可不选择素材。</small></label></div></article>`).join('')}</div><label class="editor-label gaps-label">待补输入（未解决前不能制作，每行一项）<textarea id="plan-gaps" rows="2" placeholder="仅填写当前文案或镜头确实需要、但尚未取得的输入">${esc(plan.gaps.join('\n'))}</textarea></label><label class="editor-label limitations-label">已知限制与处理（保留在制作记录中，每行一项）<textarea id="plan-limitations" rows="3" placeholder="例如：没有完整连续工序画面，因此只说明可见动作，不宣称工序完成。">${esc((plan.limitations||[]).join('\n'))}</textarea></label>${plan.notes?.length?`<div class="demo-notice">${plan.notes.map(esc).join('<br>')}</div>`:''}${plan.gaps.length?`<p class="review-blocker-hint">尚有 ${plan.gaps.length} 项待补输入。处理并保存后，确认按钮会恢复。</p>`:(plan.limitations||[]).length?'<p class="helper-text">确认后会按当前方案制作，并保留上面的已知限制与处理方式。</p>':''}<div class="review-actions"><button id="save-plan" class="button secondary" ${busy?'disabled':''}>保存修改</button><button id="approve-plan" class="button primary" ${busy||plan.stale||plan.gaps.length?'disabled':''}>${plan.gaps.length?'先处理待补输入':'确认当前文案与分镜 →'}</button></div>`;
}
function renderProduction(){const p=state.project,j=p.jobs.find(j=>j.action==='produce');const approved=p.approval?.status==='confirmed'&&!p.plan?.stale;const stages=[['importing','素材导入'],['narration','声音与字幕'],['editing','可编辑剪辑'],['exporting','导出成片'],['reviewing','校验与交付']];const current=stages.findIndex(s=>s[0]===j?.productionStage);const canResume=j&&['needs_input','interrupted','failed','cancelled','blocked'].includes(j.status);
  return `<div class="section-heading"><h2>按已确认方案制作完整视频</h2><span class="sub-count">CHATCUT</span></div><div class="production-brief"><span class="production-icon">✳</span><div><h3>${esc(p.topic||'还没有制作主题')}</h3><p>${p.duration} 秒上限 · ${esc(p.ratio)} · ${p.selected.length} 条已选素材 · ${p.narration?'AI 配音':'无新配音'} · ${p.captions?'带字幕':'无字幕'}</p><p>${approved?'✓ 已确认方案 v'+p.approval.version:'请先在「文案审阅」确认当前方案。'}</p></div></div><div class="production-stages">${stages.map(([key,name],i)=>`<div class="production-stage ${j?.status==='completed'||i<current?'complete':i===current?'current':''}"><span>${j?.status==='completed'?'✓':String(i+1).padStart(2,'0')}</span><strong>${name}</strong><small>${j?.status==='completed'?'已完成':i<current?'阶段已推进':i===current?(j?.status==='running'?'正在执行':'等待处理'):'等待实际任务'}</small></div>`).join('')}</div><div class="output-summary"><span>输出位置</span><code>${esc(p.outputRoot)}</code><button class="text-button" id="edit-output">修改文件夹</button></div><p class="stage-description">正式制作使用 ChatCut，保留素材、轨道和字幕的可编辑工程。导出完成后，工作台独立检查文件，再写入上述目录的新子文件夹。</p>${j?.editorUrl?`<a class="editor-link" href="${esc(j.editorUrl)}" target="_blank" rel="noopener noreferrer">打开当前 ChatCut 工程 ↗</a><p class="helper-text">导入和导出需要本次工程网页保持开启。如任务提示浏览器不可用，请先打开上方工程、确认已登录，再回到这里点击继续制作；原工程和已确认方案会保留。</p>`:''}${j?.questions?.length?`<div class="job-question"><strong>Agent 需要你补充：</strong>${j.questions.map(q=>`<p>${esc(q)}</p>`).join('')}</div>`:''}${canResume?'<label class="editor-label">补充给 Agent 的说明<textarea id="production-followup" rows="3" placeholder="例如：已经打开对应工程，请继续查询已有导出任务。"></textarea></label>':''}<button class="button primary production-start" data-action="produce" ${!approved||busy?'disabled':''}>✳ ${canResume?'继续制作，先核对已有任务':'调用插件，生成完整视频'}</button><p class="helper-text">启用的 AI 配音或纯音乐会使用你的 ChatCut 服务。未开启的项目不会额外生成。</p>${j?.error?`<div class="error-banner">${esc(j.error)}</div>`:''}`;
}
function renderDelivery(){const d=state.project.deliveries[0];if(!d)return `${empty('▤','成片完成后，会出现在这里。','你可以直接播放 MP4，下载文件，<br>或打开指定输出文件夹查看完整制作资料。')}<div class="output-summary"><span>当前输出位置</span><code>${esc(state.project.outputRoot)}</code></div>`;return `<div class="section-heading"><h2>成片已产出</h2><span class="delivery-badge">文件与完整解码检查通过</span></div><video class="final-video" controls preload="metadata" src="/api/files/${d.videoId}"></video><div class="delivery-meta"><p>${new Date(d.createdAt).toLocaleString('zh-CN')} · ${Number(d.verified.duration).toFixed(2)} 秒 · ${d.verified.width} × ${d.verified.height}</p><span>感知验收待按报告复核</span></div><div class="output-summary"><span>实际输出文件夹</span><code>${esc(d.directory)}</code><button class="button secondary small-button" id="open-output" data-directory="${esc(d.directory)}">打开文件夹 ↗</button></div>${d.editorUrl?`<a class="editor-link" href="${esc(d.editorUrl)}" target="_blank" rel="noopener noreferrer">继续编辑 ChatCut 工程 ↗</a>`:''}<div class="section-heading file-heading"><h2>交付文件</h2><span class="section-note">每个文件保留 SHA-256</span></div><div class="file-list">${d.files.map(f=>`<a class="file-row" href="/api/files/${f.id}?download=1" download><span class="file-icon">${f.role==='video'?'▷':f.role==='subtitles'?'CC':'▤'}</span><span><strong>${esc(f.name)}</strong><small>${(f.bytes/1024).toFixed(1)} KB · ${esc(f.sha256.slice(0,12))}…</small></span><span>下载 ↓</span></a>`).join('')}</div>${d.notes.length?`<div class="demo-notice">${d.notes.map(esc).join('<br>')}</div>`:''}`;}
function renderTaskBanner(){
  const job=state.project.jobs.find(j=>j.id===activeId),banner=$('#task-banner');
  const waiting=!!job&&['running','cancelling'].includes(job.status);
  banner.classList.toggle('hidden',!waiting);
  $('#reset-confirm').disabled=waiting;
  const note=$('#reset-task-notice');note.classList.toggle('hidden',!waiting);
  if(waiting){
    const seconds=Math.max(0,Math.floor((Date.now()-new Date(job.startedAt))/1000));const elapsed=seconds<60?seconds+' 秒':Math.floor(seconds/60)+' 分 '+seconds%60+' 秒';
    const title=job.status==='cancelling'?'正在停止当前任务':({collect:'正在采集素材',discover:'正在搜索素材',plan:'正在生成文案与分镜',produce:'正在制作视频',connect:'正在检查连接'}[job.action]||'任务执行中');
    banner.innerHTML=`<span class="source-task-spinner" aria-hidden="true"></span><div class="background-task-main"><strong>${title}<span>已用 ${elapsed}</span></strong><p>任务会继续运行，你可以切换制作步骤、预览素材和查看规则。编辑本期、新建及切换项目会在任务结束后恢复。</p><div class="background-task-actions"><button class="text-button" data-task-progress>查看执行记录 ↓</button><button class="text-button" data-task-cancel ${job.status==='cancelling'?'disabled':''}>${job.status==='cancelling'?'正在停止…':'停止当前任务'}</button></div></div>`;
    note.textContent='当前正在'+(job.label||'执行任务')+'。任务结束后即可新建；你可以先关闭此窗口，继续浏览。';
    if($('#projects-dialog').open){$('#projects-notice').dataset.taskNotice='1';$('#projects-notice').textContent='当前正在'+(job.label||'执行任务')+'，任务结束后可切换项目。项目列表、搜索和预览仍可查看。';}
  }else{
    banner.innerHTML='';note.textContent='';
    if($('#projects-notice').dataset.taskNotice){$('#projects-notice').textContent='';delete $('#projects-notice').dataset.taskNotice;}
  }
}
function renderActivity(){renderTaskBanner();const job=state.project.jobs.find(j=>j.id===activeId)||state.project.jobs[0];const usagePanel=$('#token-usage'),historyOpen=usagePanel.querySelector('details')?.open||false,historyScroll=usagePanel.querySelector('ol')?.scrollTop||0;usagePanel.innerHTML=renderTokenUsage(state.project,job,historyOpen);const historyList=usagePanel.querySelector('ol');if(historyList)historyList.scrollTop=historyScroll;const r=state.runtime;$('#plugin-version').textContent='v'+state.catalog.version;$('#connection-dot').classList.toggle('connected',r.chatcut==='connected');$('#connection-text').textContent=!r.authenticated?'Codex 尚未登录':r.chatcut==='connected'?'ChatCut 实际连接已验证':r.chatcut==='failed'?'ChatCut 检查失败':'Codex 已登录 · ChatCut 待检测';$('#check-runtime').disabled=busy;$('#activity-live').textContent=job?statuses[job.status]:'等待开始';$('#activity-live').className='activity-live '+(job?.status||'');$('#cancel-job').classList.toggle('hidden',!activeId);$('#cancel-job').disabled=job?.status==='cancelling';if(!job){$('#activity').innerHTML='<div class="activity-empty"><span class="empty-icon">⌁</span>从选择风格与素材开始。<br>每次任务会显示真实的工具调用，<br>导出排队不会被当作已交付。</div>';$('#job-receipt').classList.add('hidden');return;}
  $('#activity').innerHTML=job.events.slice(-20).map(e=>`<div class="activity-item ${e.type==='error'?'error':''}"><span class="activity-symbol">${e.type==='completed'?'✓':e.type==='tool'?'↗':'·'}</span><div class="activity-content">${esc(e.message)}<time>${new Date(e.time).toLocaleTimeString('zh-CN',{hour12:false})}</time></div></div>`).join('');const receipt=$('#job-receipt');receipt.classList.remove('hidden');const seconds=Math.max(0,Math.round((new Date(job.completedAt||Date.now())-new Date(job.startedAt))/1000));receipt.innerHTML=`<div class="receipt-top">${esc(job.label)} · ${statuses[job.status]}</div><div class="receipt-row"><span>实际等待</span><span>${seconds}s</span></div><div class="receipt-row"><span>ChatCut 工具调用</span><span>${job.toolCalls.filter(t=>/chatcut/i.test(t.server+' '+t.tool)&&t.status==='started').length}</span></div>${job.threadId?`<div class="receipt-id">SESSION<br>${esc(job.threadId)}</div>`:''}`;$('#job-attention').classList.toggle('hidden',!job.error);$('#job-attention').textContent=job.error||'';
}
function render(){if(!state)return;busy=!!activeId;renderNav();fillSettings();$('#page-title').innerHTML=esc(headings[step])+'<span>。</span>';$('#page-subtitle').textContent=subtitles[step];$('#chapter').textContent=`0${step+1} / 04`;$('#stage-content').innerHTML=[renderSources,renderReview,renderProduction,renderDelivery][step]();$('#footer-hint').textContent=['每一份素材，都保留真实来源。','确认绑定当前方案，改动后需要重新确认。','Agent 持续制作，直到导出与本地交付。','文件校验与完整观看/听审分别记录。'][step];$('#next-step').textContent=step===3?'返回选材工作台 ↻':`下一步：${labels[step+1]} →`;$('#next-step').disabled=(step===0&&!state.project.selected.length)||(step===1&&!state.project.approval)||(step===2&&!state.project.deliveries.length);if(busy)document.querySelectorAll('#stage-content input:not(#cache-query),#stage-content select,#stage-content textarea').forEach(el=>el.disabled=true);$('#new-project').disabled=false;$('#projects-toggle').disabled=false;$('#refresh-catalog').disabled=busy;document.querySelectorAll('.workbench-settings input,.workbench-settings select,.workbench-settings button').forEach(el=>el.disabled=busy);renderActivity();}
function projectStep(){const fallback=state.project.deliveries.length?3:state.project.plan?1:0;const saved=sessionStorage.getItem('frame-step:'+state.project.id);const value=saved===null?fallback:Number(saved);return Number.isInteger(value)&&value>=0&&value<=3?value:fallback;}
async function refresh(renderAll=true){const previous=state?.project.id;state=await api('/api/state');if(previous!==state.project.id)step=projectStep();activeId=state.activeJobId;selected=new Set(state.project.selected);if(!settingsDirty&&!planDirty)$('#save-status').textContent='已保存到本机';if(renderAll)render();else renderActivity();if($('#projects-dialog').open){projectChoices=state.projects||projectChoices;renderProjectList();}if(activeId)schedulePoll();}
async function navigate(next){try{if(!busy){await saveSettings();if(step===1)await savePlan();}step=next;sessionStorage.setItem('frame-step:'+state.project.id,String(step));render();window.scrollTo({top:0,behavior:'instant'});}catch(e){error(e.message);}}
async function start(action,options={}){if(busy)return;clearError();try{await saveSettings();if(step===1)await savePlan();const result=await api('/api/jobs',{action,...options});activeId=result.job.id;await refresh();schedulePoll();}catch(e){error(e.message);}}
function schedulePoll(){clearTimeout(pollTimer);pollTimer=setTimeout(poll,1200);}
async function poll(){if(!activeId)return;try{const job=await api('/api/jobs/'+activeId);const index=state.project.jobs.findIndex(j=>j.id===job.id);if(index>=0)state.project.jobs[index]=job;else state.project.jobs.unshift(job);if(step===2&&job.action==='produce')render();else renderActivity();if(step<=1&&$('#source-task-status'))$('#source-task-status').innerHTML=sourceTaskStatus();if(['running','cancelling'].includes(job.status)){schedulePoll();return;}activeId=null;await refresh();if(job.status==='completed'){if(step===0&&['discover','collect'].includes(job.action))$(job.action==='discover'?'#source-review':'#current-materials')?.scrollIntoView({behavior:'smooth',block:'start'});toast(job.summary||'任务已完成');if(job.action==='produce')await navigate(3);}else error(job.error||job.summary||'任务需要处理。');}catch(e){error('进度暂时无法读取，正在重连：'+e.message);clearTimeout(pollTimer);pollTimer=setTimeout(poll,3000);}}
async function preview(id,fromCache=false){const s=(fromCache?cachedEntries():state.project.sources).find(s=>s.id===id);if(!s)return;const ready=s.status==='ready',mediaBase=(fromCache?'/api/library/media/':'/api/media/')+id,thumbnailUrl=sourceThumbnail(s);let media='';if(ready){media=s.kind==='video'?`<video controls preload="metadata" src="${mediaBase}" poster="${s.thumbnailPath?mediaBase+'?thumbnail=1':''}"></video>`:s.kind==='image'?`<img src="${mediaBase}" alt="${esc(s.title)}">`:`<audio controls src="${mediaBase}"></audio>`;}else if(thumbnailUrl)media=`<img src="${esc(thumbnailUrl)}" alt="" referrerpolicy="no-referrer">`;else media='<p class="helper-text">当前来源没有可用的真实预览，采集成功后可在这里查看。</p>';$('#media-detail').innerHTML=`<span class="eyebrow">${fromCache?'CACHED MATERIAL':ready?'LOCAL MATERIAL':'SOURCE CANDIDATE'}</span><h2>${esc(s.title)}</h2><div class="media-player">${media}</div><p>${esc(s.description)}</p><p class="helper-text">${esc(sourceTypes[s.sourceType]||sourceTypes.other)} · ${esc(s.author||'未知作者')} · 权利状态：${esc(s.rights||'unknown')}</p>${s.dateEvidence?`<p class="helper-text">日期依据：${esc(s.dateEvidence)}</p>`:''}${s.topicFit||s.styleFit?`<dl class="source-fit">${s.topicFit?`<dt>${fromCache?'原采集题材':'题材适配'}</dt><dd>${esc(s.topicFit)}</dd>`:''}${s.styleFit?`<dt>${fromCache?'原采集风格':'风格适配'}</dt><dd>${esc(s.styleFit)}</dd>`:''}</dl>`:''}${s.verification?`<p class="helper-text">核实记录：${esc(s.verification)}</p>`:''}${s.caveats?.length?`<p class="source-caveats">待核实：${s.caveats.map(esc).join('；')}</p>`:''}${s.url?`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">查看原始内容 ↗</a>`:''}${s.repositoryCommit?`<p class="media-hash">仓库版本 ${esc(s.repositoryCommit)}<br>${esc(s.repositoryPath)}</p>`:''}${ready?`<div class="material-local"><strong>已保存到本机</strong><code>${esc(s.localPath)}</code><p>${(s.bytes/1024/1024).toFixed(2)} MB${s.duration?' · '+Number(s.duration).toFixed(2)+' 秒':''} · ${s.width||0} × ${s.height||0}</p><div><button class="button secondary small-button" ${fromCache?'data-cache-folder':'data-material-folder'}="${id}">打开所在文件夹 ↗</button><a class="text-button" href="${mediaBase}?download=1" download>下载文件 ↓</a></div></div><p class="media-hash">SHA-256 ${esc(s.sha256)}</p>${fromCache?`<button class="button primary" data-cache-use="${id}" ${busy?'disabled':''}>选用到本期</button>`:''}`:`<div class="collect-range"><label>截取起点（秒）<input id="collect-start" type="number" min="0" value="${s.start||0}"></label><label>截取终点（秒，0 表示由 Agent 选取）<input id="collect-end" type="number" min="0" value="${s.end||0}"></label></div><button class="button primary" data-collect="${id}" ${busy?'disabled':''}>调用采集 skill，保存素材到本地 ↓</button>`}`;delete $('#media-dialog').dataset.candidateId;$('#media-dialog').dataset.sourceId=id;$('#media-dialog').showModal();}
async function showSourceRules(){const rules=await api('/api/source-skill');$('#style-detail').innerHTML=`<span class="eyebrow">VIDEO STUDIO · SOURCE SKILL</span><h2 id="style-detail-title">素材采集工具</h2><p class="helper-text">以下为当前插件中实际的 skill 和来源规则，搜索与采集任务会读取这些文件。</p><pre class="source-skill-text">${esc(rules.skill)}</pre>${rules.references.map(r=>`<details class="source-skill-reference"><summary>${esc(r.name)}</summary><pre class="source-skill-text">${esc(r.text)}</pre></details>`).join('')}`;$('#style-dialog').showModal();}

