document.addEventListener('click',async e=>{const dateFilter=e.target.closest('[data-cache-window]');if(dateFilter){cacheWindow=dateFilter.dataset.cacheWindow;cacheLimit=24;$('#material-library').outerHTML=renderLibrary();return;}const filter=e.target.closest('[data-cache-filter]');if(filter){cacheFilter=filter.dataset.cacheFilter;cacheLimit=24;$('#material-library').outerHTML=renderLibrary();return;}const candidate=e.target.closest('[data-candidate-collect],[data-candidate-preview]');if(candidate){if(candidate.dataset.candidateCollect)await collectCandidate(candidate.dataset.candidateCollect);else await previewCandidate(candidate.dataset.candidatePreview);return;}const cache=e.target.closest('[data-cache-use],[data-cache-preview],[data-cache-folder]');if(cache){if(cache.dataset.cacheUse)await useCached(cache.dataset.cacheUse);else if(cache.dataset.cachePreview)await preview(cache.dataset.cachePreview,true);else try{await api('/api/library/open-folder',{id:cache.dataset.cacheFolder});}catch(err){toast(err.message);}return;}const folder=e.target.closest('[data-material-folder]');if(folder){try{await api('/api/open-material-folder',{sourceId:folder.dataset.materialFolder});}catch(err){toast(err.message);}return;}const style=e.target.closest('[data-style-detail],[data-style-use],[data-style-evidence]');if(style){try{if(style.dataset.styleDetail)await showStyle(style.dataset.styleDetail);else if(style.dataset.styleUse)await useStyle(style.dataset.styleUse);else await showEvidence(style.dataset.styleKey,style.dataset.styleEvidence);}catch(err){if($('#style-dialog').open){const box=document.createElement('p');box.className='error-banner';box.textContent=err.message;$('#style-detail').prepend(box);}else error(err.message);toast(err.message);}return;}const collect=e.target.closest('[data-collect]');if(collect){const sourceId=collect.dataset.collect;const inPreview=$('#media-dialog').open&&$('#media-dialog').dataset.sourceId===sourceId;const range=inPreview?{start:Number($('#collect-start')?.value)||0,end:Number($('#collect-end')?.value)||0}:{};$('#media-dialog').close();await start('collect',{sourceId,...range});return;}const b=e.target.closest('[data-action]');if(b){const action=b.dataset.action;await start(action,{query:$('#search-query')?.value||'',followup:$('#production-followup')?.value||''});return;}const media=e.target.closest('[data-preview]');if(media){await preview(media.dataset.preview);return;}});
