$('#media-close').addEventListener('click',()=>{$('#media-dialog').close();$('#media-detail').innerHTML='';});
let projectChoices=[];
function renderProjectList(){const query=$('#project-query').value.trim().toLocaleLowerCase();const rows=projectChoices.filter(p=>p.title.toLocaleLowerCase().includes(query));$('#projects-list').innerHTML=rows.length?rows.map(p=>`<button class="project-choice ${p.current?'is-current':''}" data-project-id="${esc(p.id)}" ${p.current?'aria-current="true"':''}><span class="project-choice-icon">${p.deliveryCount?'▷':'▤'}</span><span class="project-choice-main"><strong>${esc(p.title)}</strong><small>${esc(p.status)} · ${p.materialCount} 份素材${p.recovered?' · 已恢复':''}</small><small>创建 ${new Date(p.createdAt).toLocaleString('zh-CN')} · 更新 ${new Date(p.updatedAt).toLocaleString('zh-CN')}</small></span><span class="project-choice-action">${p.current?'当前':'打开 →'}</span></button>`).join(''):'<p class="helper-text">没有找到匹配的项目。</p>';}
async function openProjects(){try{const result=await api('/api/projects');projectChoices=result.projects;$('#project-query').value='';$('#projects-notice').textContent=result.errors.length?'有部分旧记录未能读取，已有项目仍可打开。':'';renderProjectList();$('#projects-dialog').showModal();renderTaskBanner();}catch(e){error(e.message);}}
async function flushProject(){clearTimeout(saveTimer);await saveSettings();await saving;if(planDirty)await savePlan();}
$('#projects-toggle').addEventListener('click',openProjects);
$('#projects-close').addEventListener('click',()=>$('#projects-dialog').close());
$('#project-query').addEventListener('input',renderProjectList);
$('#projects-list').addEventListener('click',async e=>{const button=e.target.closest('[data-project-id]');if(!button)return;try{if(button.dataset.projectId===state.project.id){$('#projects-dialog').close();return;}if(busy){renderTaskBanner();return;}button.disabled=true;await flushProject();await api('/api/projects/switch',{projectId:button.dataset.projectId});settingsDirty=false;planDirty=false;clearTimeout(pollTimer);await refresh();$('#projects-dialog').close();clearError();toast('已打开「'+state.project.title+'」。');window.scrollTo({top:0,behavior:'instant'});}catch(err){button.disabled=false;$('#projects-notice').textContent=err.message;}});
$('#projects-new').addEventListener('click',()=>{$('#projects-dialog').close();$('#reset-dialog').showModal();renderTaskBanner();});
$('#new-project').addEventListener('click',()=>{$('#reset-dialog').showModal();renderTaskBanner();});$('#reset-dismiss').addEventListener('click',()=>$('#reset-dialog').close());$('#reset-confirm').addEventListener('click',async()=>{try{if(busy){renderTaskBanner();return;}await flushProject();await api('/api/reset',{});settingsDirty=false;planDirty=false;$('#reset-dialog').close();await refresh();toast('新项目已建立，旧项目保存在「我的项目」。');}catch(e){error(e.message);}});
refresh().catch(e=>error('无法读取工作台：'+e.message));
